-- =============================================================
-- ESQUEMA OFICIAL SUPABASE: BANCO DE CASUÍSTICAS MINEDU / DIGERE
-- Total de registros: 54 casuísticas oficiales en 7 direcciones
-- =============================================================

CREATE TABLE IF NOT EXISTS public.minedu_casuisticas (
  id TEXT PRIMARY KEY,
  dir_id TEXT NOT NULL,
  dir_code TEXT NOT NULL,
  dir_name TEXT NOT NULL,
  number TEXT NOT NULL,
  title TEXT NOT NULL,
  criterio_title TEXT,
  criterio_desc TEXT,
  desarrollo TEXT,
  solucion TEXT,
  ejemplo TEXT,
  normativa TEXT,
  caso_especifico TEXT,
  accion TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 1. SEGURIDAD RLS
ALTER TABLE public.minedu_casuisticas ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Lectura publica casuisticas minedu" ON public.minedu_casuisticas;
CREATE POLICY "Lectura publica casuisticas minedu" 
  ON public.minedu_casuisticas FOR SELECT USING (true);

DROP POLICY IF EXISTS "Escritura publica casuisticas minedu" ON public.minedu_casuisticas;
CREATE POLICY "Escritura publica casuisticas minedu" 
  ON public.minedu_casuisticas FOR ALL USING (true);

-- 2. HABILITAR REALTIME
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables 
    WHERE pubname = 'supabase_realtime' AND tablename = 'minedu_casuisticas'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.minedu_casuisticas;
  END IF;
END $$;

-- 3. INSERCIÓN DE LAS 54 CASUÍSTICAS OFICIALES
INSERT INTO public.minedu_casuisticas (
  id, dir_id, dir_code, dir_name, number, title, criterio_title, criterio_desc, desarrollo, solucion, ejemplo, normativa, caso_especifico, accion
) VALUES
('dei-01', 'DEI', 'DEI', 'Ed. Inicial', '01', 'Cobertura de instituciones: ¿Qué materiales le corresponde a una cuna con auxiliar que no está como focalizada?', 'Cobertura de instituciones', 'Las cunas con auxiliar que no están en el listado de focalizadas pueden recibir material si están registradas como cuna.', 'Una UGEL tiene una cuna que solo recibe atención con auxiliar y no está en el listado de instituciones focalizadas. El director consulta qué materiales le debe asignar.', 'Si la institución está registrada como cuna, va a tener su material. Se ha procurado ampliar la cobertura. Para el próximo año (dotación 2028) se incorporarán 71 instituciones más, dependiendo de la región y la programación presupuestal.', 'Una cuna con auxiliar en UGEL Huamanga que no está en el listado de focalizadas: si está registrada como cuna en el registro nacional, recibe el material. Si no está registrada, debe coordinar con la DRE para su inclusión en la siguiente dotación.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('dei-06', 'DEI', 'DEI', 'Ed. Inicial', '06', 'Cantidad de material por lengua: ¿La lengua asháninka llega muy poco para 4 y 5 años?', 'Cantidad de material por lengua', 'La cantidad de material se determina con un año de anterioridad según los cuadros de estadísticas.', 'Se reporta que la lengua asháninka llega muy poco en el caso de 4 y 5 años.', 'La cantidad se ve con un año anterior. Por eso es importante que puedan llenar el SIAGIE con toda la información que requiere el Ministerio de Educación con la cantidad de estudiantes reales. Si falta algún material, siempre es bueno coordinar con la UGEL para su redistribución.', 'Lengua asháninka en Coronel Portillo: si la cantidad asignada es insuficiente, verificar el SIAGIE y coordinar redistribución con la UGEL.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', 'Desde Coronel Portillo se indica que la lengua asháninka llega muy poco en el caso de 4 y 5 años.', ''),
('dei-07', 'DEI', 'DEI', 'Ed. Inicial', '07', 'Cobertura de nuevas instituciones: ¿Las nuevas creaciones reciben material para el pueblo Awajún?', 'Cobertura de nuevas instituciones', 'Las nuevas instituciones que están en el registro reciben el material correspondiente a su pueblo originario.', 'Se consulta si las nuevas creaciones reciben material para el pueblo Awajún.', 'Todas las instituciones que están dentro del registro reciben el material. En el caso del pueblo Awajún, sí hay cuadernos de trabajo. Todas las instituciones que están como revitalización reciben el cuaderno de inicial Crea y Resuelve.', 'Nueva IE con pueblo Awajún: si está en el registro como revitalización, recibe el cuaderno Crea y Resuelve de DEI.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('dei-12', 'DEI', 'DEI', 'Ed. Inicial', '12', 'Cobertura de PRONOEI: ¿Los PRONOEI reciben cuadernos de trabajo?', 'Cobertura de PRONOEI', 'Los PRONOEI reciben cuadernos de trabajo siempre y cuando estén en el registro nacional.', 'Se reporta que este mes se está realizando el cierre y creación de PRONOEI. ¿A qué provincia le va a considerar en la distribución?', 'Los PRONOEI también llegan a los cuadernos de trabajo, siempre y cuando estén en el registro nacional. Si es una nueva creación y todavía no está en el registro, ahí corresponde esperar la redistribución y poder dialogar directamente con la UGEL.', 'Nuevo PRONOEI en UGEL Fajardo: si está en el registro nacional, recibe cuadernos. Si no está, coordinar con la UGEL para la siguiente dotación.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', 'Desde UGEL Fajardo se indica que este mes se está realizando el cierre y creación de PRONOEI. ¿A qué provincia le va a considerar en la distribución?', ''),
('dei-13', 'DEI', 'DEI', 'Ed. Inicial', '13', 'Solicitud de material específico: ¿Se puede atender con materiales de trabajo para el idioma Harakbut?', 'Solicitud de material específico', 'Las solicitudes de material específico para lenguas sin programación deben ser coordinadas con la UGEL.', 'Se reporta que atender con algunos materiales de trabajo, como en el caso de Idioma Harakbut con cuadernos de trabajo para 3 años.', 'Es importante tener una indicación por parte de los especialistas respecto a estas solicitudes. Se toma nota para la coordinación interna.', 'Solicitud de material para Harakbut en UGEL Manu: no hay material programado para esta lengua en 4 y 5 años. Se puede coordinar redistribución de material en castellano.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', 'Desde UGEL Manu se solicita poder atender con algunos materiales de trabajo, como en el caso de Idioma Harakbut con cuadernos de trabajo para 3 años.', ''),
('dep-00', 'DEP', 'DEP', 'Ed. Primaria', '00', 'Cambio de característica de una institución educativa: ¿a qué dirección corresponde asignar los materiales?', 'DEP – DISER', 'Asignación de materiales educativos por cambio de característica de la institución educativa en el MC SIGA.', 'La UGEL identifica una institución educativa que ha cambiado de característica (ya envió la solicitud de habilitación de códigos modulares) y tiene dudas sobre a qué dirección debe asignar los materiales educativos: si debe considerar la característica registrada por el MINEDU o la información actualizada que maneja la UGEL.', 'La UGEL debe verificar la característica actual que corresponde a la institución educativa y efectuar la asignación de materiales según corresponda. Al finalizar, en el MC SIGA, solo debe quedar asignado el material correspondiente a dicha institución educativa.', 'Por ejemplo, un mismo código modular no puede tener asignados materiales educativos de DEP y DISER a la vez. Asimismo, se debe verificar que la reasignación de los recursos no deje desabastecidas a las II. EE. que anteriormente tenían otra característica.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.
Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo y asignación de materiales en el MC SIGA según característica de la IE.', '', ''),
('dep-11', 'DEP', 'DEP', 'Ed. Primaria', '11', 'Criterio de distribución de bibliotecas: ¿El cálculo de bibliotecas se hace por secciones o por aula?', 'Criterio de distribución de bibliotecas', 'La distribución de bibliotecas se hace por aula, no por secciones.', 'La UGEL Ambo asignó una cantidad mayor de libros de biblioteca. Al parecer, el cálculo lo hicieron por secciones y no por aula.', 'Nosotros no distribuimos para secundaria. Esto es para inicial. La distribución de bibliotecas se hace por aula.', 'UGEL Ambos asignó más libros de los correspondientes: verificar que el cálculo sea por aula, no por secciones.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('dep-16', 'DEP', 'DEP', 'Ed. Primaria', '16', 'Cobertura de cuadernillos: ¿Los cuadernillos de trabajo de primero y segundo grado son solo para unidocentes?', 'Cobertura de cuadernillos', 'Los cuadernillos de comunicación y matemática son para unidocentes, multigrado urbano y polidocente completas.', 'Se consulta si los cuadernillos de trabajo de primero y segundo grado son solo para las unidocentes o para todas.', 'Los cuadernillos de comunicación y matemática son para las unidocentes y multigrado del ámbito urbano, y las polidocente completas. Incluidas las EIB de fortalecimiento en el caso de las F4 y las de rehabilitación que son de R1, R2 y R3.', 'Una polidocente completa monolingüe castellano recibe cuadernillos de comunicación y matemática de primero y segundo grado.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('dep-19', 'DEP', 'DEP', 'Ed. Primaria', '19', 'Materiales programados 2027: ¿Para el 2027 habrá cuadernos de trabajo y textos de ciencia y tecnología o personal social?', 'Materiales programados 2027', 'Los cuadernillos de comunicación y matemática sí están programados. Los textos de ciencia y tecnología y personal social aún no.', 'Adriano Silva consulta: para el año 2027 dará un cuaderno de trabajo y textos de ciencia y tecnología o de personal social?', 'Los cuadernillos de trabajo son de comunicación y matemática de primer y segundo grado. Los textos de ciencia y tecnología y personal social todavía no han sido teorizados. Tal vez para más adelante.', 'Dotación 2027: se entregan cuadernillos de comunicación y matemática de 1er y 2do grado. No se entregan textos de ciencia y tecnología ni personal social.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('dep-20', 'DEP', 'DEP', 'Ed. Primaria', '20', 'Cantidad de biblioteca por grado: ¿Cuántos ejemplares de biblioteca se entregan a una unidocente con estudiantes de varios grados?', 'Cantidad de biblioteca por grado', 'La cantidad de libros de biblioteca depende del número de estudiantes por grado.', 'Si en una institución tengo 5 estudiantes de primero, 2 de segundo y 1 de cuarto, ¿se debe entregar un ejemplar de los 28 títulos?', 'Si tienes 1 de primero, le tendrías que dar sus 4 ejemplares de primer grado. Si tuviese de segundo grado 2 niños, le tendría que dar. Y si no tiene nada, igual va a recibir su ejemplar.', 'Unidocente con 5 de primero, 2 de segundo y 1 de cuarto: recibe 4 títulos de primero, 4 de segundo y 4 de cuarto.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('dep-23', 'DEP', 'DEP', 'Ed. Primaria', '23', 'Textos multinivel: ¿Se están elaborando textos multinivel para primaria?', 'Textos multinivel', 'No se han programado textos multinivel para la dotación 2027.', 'Se indica que en un taller anterior de fortalecimiento les mencionaron que estaban elaborando textos multinivel para primaria y que serían entregados el 2027.', 'No, por el momento no se han hablado de esos textos multinivel. No está programado, no está presupuestado. La dotación 2027 está con la RM 373.', 'Textos multinivel: no están programados para la dotación 2027. No hay información oficial sobre su elaboración.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('dep-27', 'DEP', 'DEP', 'Ed. Primaria', '27', 'Criterio de distribución de bibliotecas: ¿Cómo se considera el aula en la distribución de bibliotecas en una unidocente?', 'Criterio de distribución de bibliotecas', 'La distribución de bibliotecas se hace por aula, no por toda la institución.', 'En el material de distribución del material de biblioteca en una institución unidocente, ¿cómo se considerará el aula por grado o por toda la institución?', 'Se considera por aula. Pero hay cuadernos que son dirigidos para tercero y cuarto grado. Y si hay estudiantes de tercero y cuarto grado, sí se da el número correspondiente. A veces tenemos material de primero a sexto, otros de tercero y cuarto, otros solamente de quinto y sexto. Se le da de acuerdo a los grados que hay en esa institución.', 'Unidocente con estudiantes de 1ro, 2do y 4to: recibe 4 títulos de 1ro, 4 de 2do y 4 de 4to.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('dep-35', 'DEP', 'DEP', 'Ed. Primaria', '35', 'Cobertura de textos: ¿Los textos y cuadernillos de matemática y comunicación son para todas las instituciones?', 'Cobertura de textos', 'Los cuadernos de nivelación de matemáticas y comunicación son para todos los modelos de atención.', 'Se consulta si los textos y cuadernillos de matemática y comunicación deberían ser para todas las instituciones, sobre todo los textos que corresponden por tipo de atención.', 'Los cuadernos de nivelación de matemáticas y comunicación son para todos los modelos, para los 3 modelos que atendemos.', 'Los 3 modelos de DISER (alternancia, residencia estudiantil y tutorial) reciben cuadernos de nivelación de matemáticas y comunicación.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('dep-40', 'DEP', 'DEP', 'Ed. Primaria', '40', 'Cobertura de material: ¿Ya van 2 años que no les atiende con material de primaria en UGEL Paucartambo?', 'Cobertura de material', 'Si una institución no recibe material desde hace años, se debe verificar su caracterización.', 'Se reporta que ya van 2 años que no les atiende con material de primaria.', 'Tendríamos que ver si están dentro de la caracterización. Por favor, en todo caso, invito al especialista que haga la consulta a través del correo de manera directa.', 'IE en UGEL Paucartambo sin material por 2 años: verificar caracterización y coordinar por correo.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', 'Desde UGEL Paucartambo se indica que ya van 2 años que no les atiende con material de primaria.', ''),
('dep-52', 'DEP', 'DEP', 'Ed. Primaria', '52', 'Criterio de distribución de bibliotecas: ¿Cómo se considera el aula en la distribución de bibliotecas en una unidocente?', 'Criterio de distribución de bibliotecas', 'La distribución de bibliotecas se hace por aula, no por toda la institución.', 'En el material de distribución del material de biblioteca en una institución unidocente, ¿cómo se considerará el aula por grado o por toda la institución?', 'Se considera por aula. Pero hay cuadernos que son dirigidos para tercero y cuarto grado. Y si hay estudiantes de tercero y cuarto grado, sí se da el número correspondiente. A veces tenemos material de primero a sexto, otros de tercero y cuarto, otros solamente de quinto y sexto. Se le da de acuerdo a los grados que hay en esa institución.', 'Unidocente con estudiantes de 1ro, 2do y 4to: recibe 4 títulos de 1ro, 4 de 2do y 4 de 4to.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('des-14', 'DES', 'DES', 'Ed. Secundaria', '14', 'Banco de libros y vigencia de textos: ¿Cuál es el criterio para distribuir los textos escolares a instituciones atendidas desde el 2025?', 'Banco de libros y vigencia de textos', 'Los textos tienen una vigencia mínima de 3 años. Las UGEL deben gestionar la devolución y reposición.', 'Se consulta cuál es el criterio para distribuir los textos escolares a las instituciones educativas que fueron atendidas desde el 2025.', 'El 2025 se atendieron a las unidocentes y multigrado urbano y las polidocente completas. Los textos de matemáticas tienen vigencia hasta el 2027. Los de comunicación hasta el 2028. Si faltan textos, la UGEL debe hacer la redistribución con otras instituciones que tengan saldos.', 'IE atendida en 2025 con textos de matemáticas: si están en buen estado, pueden usarlos hasta el 2027. Si están deteriorados, la UGEL gestiona la reposición.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('des-15', 'DES', 'DES', 'Ed. Secundaria', '15', 'Reposición de textos: ¿Cuál es el proceso de reposición si hay pérdida o déficit de textos?', 'Reposición de textos', 'Ante pérdida o déficit, se debe reportar a la UGEL y seguir el procedimiento de redistribución.', 'En caso de pérdida o déficit en institución educativa, los textos de comunicación y matemática de 3 a 6 grado, si no hay saldo en almacén UGEL, ¿cuál es el proceso para reposición?', 'Tendría que reportarlo. El año pasado se debió tener un reporte de cómo fue en la UGEL, su reporte recojo de información. Si hay pérdida, debieron actuar de acuerdo a la norma. Este año, si al niño le ha faltado y la UGEL lo tiene, tendríamos que ver en qué UGEL hay saldos que le podría permitir hacer esa redistribución.', 'Pérdida de textos en una IE: reportar a la UGEL. La UGEL verifica saldos en otras instituciones y gestiona la redistribución.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('des-17', 'DES', 'DES', 'Ed. Secundaria', '17', 'Banco de libros: ¿En qué área se hace el levantamiento de información del Banco de Libro?', 'Banco de libros', 'El levantamiento de información del Banco de Libro debe ser realizado por los especialistas de la UGEL.', 'Se consulta en qué área debe ser el levantamiento de información acerca del Banco del Libro.', 'Deberían hacerlo de acuerdo a la norma, utilizando un formato. En los oficios que se enviaron se adjuntaron los formatos, los cuales deberían ser elaborados por cada especialista.', 'Levantamiento de información del Banco de Libro: los especialistas de la UGEL deben hacerlo usando el formato adjunto en el oficio.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('des-18', 'DES', 'DES', 'Ed. Secundaria', '18', 'Cambio de caracterización: ¿Se distribuye material a polidocente completas que ahora son multigrado?', 'Cambio de caracterización', 'Las instituciones que cambiaron de caracterización deben ser atendidas según su nueva caracterización.', 'Las instituciones educativas que están caracterizadas como polidocente completo 2026, con nueva caracterización ya son consideradas como multigrados. Sin embargo, en el cuadro de distribución para el 2027 siguen considerados como polidocente completas.', 'Sí tendrían que atender esas instituciones educativas. Si es una polidocente completa y para el 2027 ya es una multigrado, pero es una multigrado de repente rural, tendrían que hacer la consulta al área de rural para poder atender con materiales. No es que se quede sin atención.', 'IE que era polidocente completa y ahora es multigrado rural: debe ser atendida por el área de rural, no por primaria.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('des-21', 'DES', 'DES', 'Ed. Secundaria', '21', 'Duplicidad de instituciones: ¿Hay instituciones que aparecen en dos direcciones (DEP y DISER)?', 'Duplicidad de instituciones', 'Las instituciones no deben estar duplicadas. Verificar si es rural o urbano.', 'Se indica que hay institutions que en el cuadro de distribución están como de una dirección y también aparecen en DISER.', 'Tendría que verificar si es rural o es urbano en el caso del multigrado. Es muy difícil que se duplique, salvo el caso de que hayan solicitado su cambio.', 'IE que aparece en DEP y DISER: verificar si es rural o urbano. Corregir la caracterización en el SIGA.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('des-31', 'DES', 'DES', 'Ed. Secundaria', '31', 'Distribución por grado: ¿Si un grado no cuenta con estudiantes, se le considera 0 en distribución o mínimamente 1?', 'Distribución por grado', 'Si un grado no cuenta con estudiantes, se le considera mínimamente 1 ejemplar.', 'Se consulta si el grado no cuenta con estudiantes, se le considera 0 en distribución o mínimamente 1.', 'Mínimamente, 1.', 'Grado sin estudiantes: se le asigna mínimamente 1 ejemplar de cada título.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('des-38', 'DES', 'DES', 'Ed. Secundaria', '38', 'Distribución por grado: ¿Se asigna material a grados que no cuentan con estudiantes?', 'Distribución por grado', 'La distribución se basa en el censo educativo. Si un grado no tiene estudiantes, se evalúa la situación.', 'Se consulta si hay algunos grados que no cuentan con estudiantes, ¿de igual manera se asignaría el material?', 'Esta distribución se ha preparado en base al censo educativo 2025. Entonces tendríamos que evaluar qué sucede con esa información, ¿por qué no se ha levantado de manera adecuada?', 'Grado sin estudiantes en el censo: evaluar con la UGEL por qué no se levantó la información.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('diser-00', 'DISER', 'DISER', 'Servicios Rurales', '00', 'Cambio de característica de una institución educativa: ¿a qué dirección corresponde asignar los materiales?', 'DEP – DISER', 'Asignación de materiales educativos por cambio de característica de la institución educativa en el MC SIGA.', 'La UGEL identifica una institución educativa que ha cambiado de característica (ya envió la solicitud de habilitación de códigos modulares) y tiene dudas sobre a qué dirección debe asignar los materiales educativos: si debe considerar la característica registrada por el MINEDU o la información actualizada que maneja la UGEL.', 'La UGEL debe verificar la característica actual que corresponde a la institución educativa y efectuar la asignación de materiales según corresponda. Al finalizar, en el MC SIGA, solo debe quedar asignado el material correspondiente a dicha institución educativa.', 'Por ejemplo, un mismo código modular no puede tener asignados materiales educativos de DEP y DISER a la vez. Asimismo, se debe verificar que la reasignación de los recursos no deje desabastecidas a las II. EE. que anteriormente tenían otra característica.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.
Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo y asignación de materiales en el MC SIGA según característica de la IE.', '', ''),
('diser-08', 'DISER', 'DISER', 'Servicios Rurales', '08', 'Redistribución de material: ¿Qué hacer cuando una institución no recibe material desde hace más de 3 años?', 'Redistribución de material', 'Si una institución no recibe material desde hace años, se debe coordinar con la UGEL para verificar la redistribución.', 'Se reporta que su institución no recibe por más de 3 años materiales educativos. ¿Cómo se solicita en este caso?', 'Ahí tiene que coordinar con su UGEL. Si no reciben, verificar el pueblo Machiguenga. También está el Asháninka, pero en mayor población es el pueblo Machiguenga. Se están brindando materiales para la biblioteca también para el pueblo Machiguenga.', 'IE en UGEL Manu sin material por 3 años: coordinar con la UGEL para verificar redistribución y confirmar que está en el registro nacional.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', 'Desde UGEL Manu se indica que su institución no recibe por más de 3 años materiales educativos. ¿Cómo se solicita en este caso?', ''),
('diser-32', 'DISER', 'DISER', 'Servicios Rurales', '32', 'Plazos de asignación: ¿Qué fecha inicia la asignación de materiales y cuál es la fecha límite?', 'Plazos de asignación', 'La asignación de materiales tiene un plazo establecido en el Oficio 32.', 'Se consulta qué fecha inicia la asignación de materiales y cuál es la fecha límite para la asignación.', 'Hay todo un proceso indicado en la normativa de materiales. El proceso empieza desde cuando se solicita a la dirección a la unidad de estadística el censo. Ya estamos en ese proceso. Según el Oficio 32, el plazo es del 30 de septiembre al 22 de octubre.', 'Asignación de materiales: plazo del 30 de septiembre al 22 de octubre según el Oficio 32.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('diser-33', 'DISER', 'DISER', 'Servicios Rurales', '33', 'Material complementario: ¿Las pizarras acrílicas son 5 por institución sin importar la cantidad de estudiantes?', 'Material complementario', 'Las pizarras acrílicas se entregan por institución, sin importar la cantidad de estudiantes.', 'Se consulta si las pizarras acrílicas son 5 por institución educativa, sin importar la cantidad de estudiantes.', 'Sí, se ha determinado la entrega de estas 5. De acuerdo al techo presupuestal que tenemos para poder hacer la adquisición de estas pizarras.', 'Pizarras acrílicas: 5 por institución educativa, sin importar la cantidad de estudiantes.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('diser-34', 'DISER', 'DISER', 'Servicios Rurales', '34', 'Material para especialistas: ¿Los materiales del DISER secundario también se distribuyen a los especialistas?', 'Material para especialistas', 'La dotación 2027 prioriza la entrega de materiales al estudiante y a la institución educativa.', 'Se consulta si los materiales del DISER secundario también se distribuyen a los especialistas.', 'Se ha priorizado para la dotación 2027 la entrega de materiales al estudiante y a la institución educativa. Esto debido al hecho presupuestal que se debe considerar.', 'DISER secundario 2027: no se distribuye material a especialistas. Se prioriza estudiantes e instituciones.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('diser-36', 'DISER', 'DISER', 'Servicios Rurales', '36', 'Excedentes de material: ¿En caso de excedentes de material fungible, los directores deben devolverlo a la UGEL?', 'Excedentes de material', 'Ante excedentes de material fungible, se debe disminuir la asignación al siguiente año.', 'Se consulta en caso de excedentes o de excedencia en material fungible (lápices, lapiceros, tijeras, etc.), si los directores deben de volver al UGEL.', 'En caso de que hubiera una excedencia, se ha considerado y evaluado a nivel de estadística. De todas maneras, si hubiera una excedencia, se debe disminuir esos materiales a los estudiantes que están en la institución educativa.', 'Excedentes de lápices en una IE: se debe disminuir la asignación al siguiente año.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('diser-37', 'DISER', 'DISER', 'Servicios Rurales', '37', 'Cambio de caracterización: ¿Se puede entregar menos de 7 unidades de libros si cambió la caracterización de DEIB a DISER?', 'Cambio de caracterización', 'Si una institución cambió de caracterización, se debe respetar la nueva asignación.', 'El UGEL ha cambiado la caracterización de algunas instituciones educativas, pasando de DEIB a DISER. ¿Es posible entregar menos de 7 unidades, por ejemplo 6 o 5 unidades con la finalidad de que alcance?', 'Si esta caracterización no está comprendida dentro del monto, tendríamos que hacer la consulta respectiva. No se puede tomar una decisión en este momento. Yo invitaría al especialista, en todo caso, que nos escriba al correo para poder directamente hacer las consultas respectivas.', 'IE que cambió de DEIB a DISER: no se puede entregar menos de 7 unidades. El especialista debe escribir al correo para la consulta.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('diser-39', 'DISER', 'DISER', 'Servicios Rurales', '39', 'Distribución de material: ¿No ha llegado el material DISER de nivel secundario este año?', 'Distribución de material', 'Si no ha llegado el material, se debe evaluar por qué no llegó a esa institución.', 'Desde la UGEL La Convención se indica que no ha llegado el material DISER de nivel secundario este año.', 'Tenemos el reporte de distribución de los tableros y nos indicaron que ya estaba cerrado el proceso de distribución. En todo caso, habría que evaluar y ver por qué esos materiales no han llegan a esa institución específicamente. Salvo que fuera una creación nueva, no de una institución.', 'IE en UGEL La Convención sin material DISER: evaluar si es una creación nueva o si hubo un error en la distribución.', 'Oficio Múltiple N.° 032-2026-MINEDU/VMGP/DIGERE — Orientaciones para el monitoreo de asignación de materiales en el MC SIGA.', '', ''),
('diser-42', 'DISER', 'DISER', 'Servicios Rurales', '42', 'Entrega de material: ¿En DISER no han entregado cuadernos de trabajo este año, solo un globo terráqueo y guías?', 'Entrega de material', 'Los cuadernos de autoaprendizaje se entregan para la dotación 2028, no 2027.', 'Se indica que en DISER no han entregado cuadernos de trabajo este año, solo un globo terráqueo y guías.', 'Solamente si efectivamente recién se está entregando para la dotación 2028. Se había entregado textos y los textos tienen una duración de 3 años. Ya este año termina la vigencia de estos textos y por eso recién en la dotación 2027 se van a entregar estos cuadernos de autoaprendizaje.', 'DISER 2027: no se entregan cuadernos de autoaprendizaje. Se entregan textos que tienen vigencia de 3 años.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('diser-43', 'DISER', 'DISER', 'Servicios Rurales', '43', 'Diversidad textual: ¿Hay posibilidad de dotar de libros con diversidad textual y no solo cuentos?', 'Diversidad textual', 'Por ahora se entregan cuadernos de trabajo. La diversidad textual se evaluará más adelante.', 'Se consulta si hubiera una posibilidad de dotar de libros que tengan diversidad textual y no solamente cuentos para desarrollar la competencia lectora.', 'A nivel de la dirección se ha considerado por ahora, manejando el techo presupuestal que tenemos, entregar cuadernos de trabajo. Más adelante iremos evaluando la posibilidad.', 'Diversidad textual: no está programada para la dotación 2027. Se evaluará para la siguiente.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('diser-44', 'DISER', 'DISER', 'Servicios Rurales', '44', 'Socialización de propuestas: ¿Se debe realizar una socialización previa de propuestas de materiales con especialistas regionales?', 'Socialización de propuestas', 'Se considera importante la socialización previa. Se toma en cuenta para futuras dotaciones.', 'Se considera que para la dotación del 2028 se debe realizar una socialización previa de propuestas de materiales con los especialistas regionales o de UGEL, para que estos puedan ser pertinentes al contexto.', 'Esta consideración la vamos a tener en cuenta. Vamos a informar para poder tener todas las consideraciones correspondientes.', 'Dotación 2028: se considerará la socialización previa con especialistas regionales.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('diser-45', 'DISER', 'DISER', 'Servicios Rurales', '45', 'Material para especialistas: ¿Se han considerado materiales para los especialistas de UGEL?', 'Material para especialistas', 'Sí se ha considerado material para los especialistas de UGEL.', 'Se consulta si se han considerado materiales para los especialistas de UGEL.', 'Sí, sí se ha considerado.', 'Material para especialistas de UGEL: sí está considerado en la dotación 2027.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('deib-03', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '03', 'Priorización de lenguas: ¿Por qué no se visualiza material para la lengua Harakbut en 4 y 5 años?', 'Priorización de lenguas', 'La elaboración de materiales en lenguas originarias es progresiva. No todas las lenguas tienen material para todos los grados.', 'Se reporta que en la presentación no se visualiza materiales para la lengua Harakbut y no se atiende con material para 4 o 5 años.', 'La elaboración del material va de manera progresiva. No se va a distribuir material de Harakbut para 4 y 5 años para el estudiante aún. Lo que va a llegar es material de biblioteca para las instituciones.', 'Lengua Harakbut en UGEL Manu: no hay cuadernos de trabajo para 4 y 5 años en esta dotación, pero sí recibe material de biblioteca.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', 'Desde UGEL Manu se indica que en la presentación no se visualiza materiales para la lengua Harakbut y no se atiende con material para 4 o 5 años.', ''),
('deib-05', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '05', 'Registro nacional de instituciones: ¿Las nuevas creaciones de instituciones EIB reciben material?', 'Registro nacional de instituciones', 'Todas las instituciones que están dentro del registro nacional de instituciones EIB reciben material.', 'Desde UGEL La Convención se consulta si las nuevas creaciones de instituciones EIB reciben material, ya que se está creando una nueva UGEL.', 'Todos los materiales llegan según el registro nacional de instituciones EIB. Si se ha creado una nueva institución y todavía no está en el registro, hay que esperar la redistribución y poder dialogar directamente con la UGEL.', 'Nueva IE EIB creada en UGEL La Convención: si está en el registro nacional, recibe material. Si no está, debe esperar la siguiente dotación o coordinar la redistribución.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-09', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '09', 'Redistribución de material: ¿Hay déficit en EIB y cómo se solicita?', 'Redistribución de material', 'Ante un déficit de material, se debe coordinar con la UGEL para la redistribución.', 'Se reporta que la UGEL identifica que tenía un déficit en EIB.', 'Todo lo que son las cantidades es de acuerdo a los cuadros de estadísticas que se hace con un año de anterioridad. Es coordinar con su UGEL para ver la redistribución.', 'Déficit en EIB en UGEL Bilimasa: coordinar con la UGEL para redistribuir material de otras instituciones que tengan excedentes.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', 'La UGEL Bellavista indica que tenía un déficit en EIB.', ''),
('deib-22', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '22', 'Lenguas en distribución progresiva: ¿La UGEL La Convención no llegará con cuadernos de trabajo de 4 y 5 años para la lengua machiguenga?', 'Lenguas en distribución progresiva', 'La elaboración de materiales en lenguas originarias es progresiva. No todas las lenguas tienen material.', 'De acuerdo al Oficio 32, la UGEL La Convención no llegará con cuadernos de trabajo de 4 y 5 años para la lengua machiguenga. Tienen una cantidad alta de estudiantes.', 'Si todavía no se ha elaborado, se tiene proyectado para la siguiente dotación. Nosotros vamos avanzando de manera progresiva. Por los recursos presupuestales y humanos, vamos de poco a poco.', 'Lengua machiguenga en UGEL La Convención: no hay cuadernos de trabajo para 4 y 5 años en esta dotación. Se proyectará para la siguiente.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-24', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '24', 'Materiales por forma de atención: ¿Qué materiales corresponden a las instituciones de fortalecimiento y revitalización en UGEL Puno?', 'Materiales por forma de atención', 'Las instituciones de fortalecimiento reciben cuadernos de trabajo. Las de revitalización reciben fichas de lengua originaria.', 'Desde UGEL Puno se consulta qué materiales corresponde a las instituciones educativas de fortalecimiento y revitalización.', 'Dentro del cuadro de distribución está la lista de materiales. Si es de revitalización, van las fichas de trabajo de lengua originaria como segunda lengua para primero y segundo grado. Y si es de fortalecimiento, van los cuadernos de trabajo de primero y segundo grado, y también cuadernos de fichaje de trabajo de matemática.', 'IE de fortalecimiento en UGEL Puno: recibe cuadernos de trabajo de comunicación y matemática de 1er y 2do grado. IE de revitalización: recibe fichas de lengua originaria.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', 'Desde UGEL Puno se consulta qué materiales corresponde a las instituciones educativas de fortalecimiento y revitalización.', ''),
('deib-25', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '25', 'Materiales por lengua: ¿La UGEL 14 (Oyón) con EIB de rehabilitación debe recibir material de quechua central?', 'Materiales por lengua', 'Las instituciones EIB de rehabilitación reciben material según su lengua originaria.', 'Si la UGEL 14 tiene EIB de rehabilitación inicial, primaria y secundaria, ¿deben llegar material que corresponde a quechua central?', 'Todo está en el registro. Todos los materiales llegan de acuerdo al registro de instituciones educativas EIB. A veces llega de un pueblo porque han considerado como segunda lengua otra lengua.', 'IE EIB de rehabilitación en UGEL 14 con quechua central: recibe material en quechua central según el registro nacional.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-26', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '26', 'Error de asignación de material: ¿Hay fichas de la lengua cucamiria que se enviaron a Yurimaguas y son de lengua Shawi?', 'Error de asignación de material', 'Si hay un error en la asignación de material por lengua, se debe corregir con la UGEL.', 'Se indica que hay fichas de la lengua cucamiria que se enviaron a Yurimaguas, pero es de lengua Shawi.', 'Ahí ha habido una confusión seguro. Eso ha sucedido en Yurimaguas porque ahí tienen sus camas. Y también Shawi. Debe haber ahí dialogar directamente con la UGEL. Quizá ha habido una confusión de la llegada. Si la institución educativa Shawi no tendría que llegar cucama y viceversa.', 'IE Shawi en Yurimaguas que recibió fichas de cucamiria: error de asignación. Corregir con la UGEL.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-28', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '28', 'Instituciones multilingües: ¿Es pertinente programar material en quechua central y aimara para una institución con 2 lenguas originarias?', 'Instituciones multilingües', 'Las instituciones con más de una lengua originaria deben ser evaluadas internamente.', 'En UGELambo se indica que para una institución educativa se ha programado material en quechua central y aimara, porque dicha institución tiene como lengua originaria 2 el aimara. ¿Es un criterio pertinente?', 'Esa sí es una pregunta para responderle interno. Tendremos que hacerlo directamente con la UGEL, teniendo en cuenta nuestro registro.', 'IE con quechua central y aimara en UGELambo: evaluar internamente la asignación de material.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-29', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '29', 'Caracterización EIB: ¿Cuándo se inicia la caracterización de EIB en instituciones educativas?', 'Caracterización EIB', 'La caracterización de EIB se realiza según el registro nacional. Las instituciones sin estudiantes EIB pueden solicitar el cambio.', 'Se consulta cuándo se va a iniciar la caracterización de EIB en instituciones educativas. Hay algunas que no tienen estudiantes en EIB pero siguen considerando esta característica.', 'Para el presente año no tenemos fecha. Tendríamos que preguntar al equipo de planificación. Sería una consulta también interna.', 'IE sin estudiantes EIB que no quiere recibir material EIB: puede solicitar el cambio de caracterización al equipo de planificación.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-30', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '30', 'Asignación por segunda lengua: ¿Por qué se asignan textos en asháninka a instituciones que tienen como segunda lengua el gine?', 'Asignación por segunda lengua', 'Si una institución tiene una segunda lengua representativa, se le provee material en ambas lenguas.', 'Desde Atalaya se observa que para la entrega de un texto, como en el caso de la lengua gine, les están asignando textos en la lengua asháninka como opción 2 y viceversa.', 'Ahí sucede que cuando ingresa la información y dentro de nuestro registro también está que hay una segunda lengua que está el gine. Y como segunda lengua, hay una cantidad representativa de estudiantes asháninka. Es por eso que se le provee el material tanto en gine como en asháninka. También tendría que volver a verificar cómo está caracterizada la institución educativa.', 'IE con gine como lengua materna y asháninka como segunda lengua: recibe material en ambas lenguas.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-41', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '41', 'Material EIB: ¿Las instituciones EIB no les dan el material de DISER?', 'Material EIB', 'Las instituciones EIB reciben material en castellano. Se debe verificar la caracterización.', 'Se indica que a las instituciones educativas EIB no les dan el material de DISER.', 'Nosotros a nivel de dirección elaboramos material con el castellano. No sé qué característica específicamente o qué lengua puede tener esa institución. En todo caso, habría que coordinar ese proceso.', 'IE EIB que no recibió material DISER: verificar caracterización y coordinar con la UGEL.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-46', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '46', 'Lenguas en distribución progresiva: ¿Por qué no hay materiales en lengua originaria para el pueblo One Piece?', 'Lenguas en distribución progresiva', 'La elaboración de materiales en lenguas originarias es progresiva.', 'Se consulta por qué no hay materiales en lengua originaria para el pueblo One Piece.', 'Nosotros realizamos o dotábamos materiales en forma progresiva. De repente, en esta dotación no se va a dotar, pero en la siguiente sí. Para el caso One Piece, sí hay los cuadernos de trabajo de primer y segundo grado para el pueblo One Piece.', 'Lengua One Piece: no hay material en esta dotación, pero sí hay cuadernos de trabajo de 1er y 2do grado.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-47', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '47', 'Lenguas por UGEL: ¿Se debe hacer una consideración a las lenguas que existen en cada UGEL y no enviar de otras lenguas?', 'Lenguas por UGEL', 'La distribución se hace según el registro nacional. Las lenguas se asignan según la caracterización.', 'Se indica que se debería hacer una consideración a las lenguas que existen en cada UGEL y no enviar de algunas otras lenguas.', 'De todas maneras, está esta indicación que nos están haciendo. Se va a tener en consideración.', 'Lenguas por UGEL: se considerará para futuras dotaciones, pero la distribución actual se hace según el registro nacional.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-48', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '48', 'Asignación por registro: ¿En el 2026 la UGEL Mainaz recibió textos de lenguas que ya no hay en la jurisdicción como Tikuna?', 'Asignación por registro', 'La distribución se hace según el registro elaborado en 2025. Si hay modificaciones, se verán en las próximas dotaciones.', 'Se indica que en el 2026 la UGEL Mainaz recibió textos de lenguas que ya no hay en la jurisdicción como Tikuna, entre otros.', 'Nosotros estamos. La distribución se hace de acuerdo al registro que está elaborado en 2025. Si es que hay alguna modificación o una actualización, eso se verá en las próximas dotaciones.', 'UGEL Mainaz recibió textos de Tikuna: la distribución se hizo según el registro 2025. Las actualizaciones se verán en las próximas dotaciones.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-49', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '49', 'Materiales por forma de atención: ¿Qué materiales corresponden a las instituciones de fortalecimiento y revitalización en UGEL Puno?', 'Materiales por forma de atención', 'Las instituciones de fortalecimiento reciben cuadernos de trabajo. Las de revitalización reciben fichas de lengua originaria.', 'Desde UGEL Puno se consulta qué materiales corresponde a las instituciones educativas de fortalecimiento y revitalización.', 'Dentro del cuadro de distribución está la lista de materiales. Si es de revitalización, van las fichas de trabajo de lengua originaria como segunda lengua para primero y segundo grado. Y si es de fortalecimiento, van los cuadernos de trabajo de primero y segundo grado, y también cuadernos de fichaje de trabajo de matemática.', 'IE de fortalecimiento en UGEL Puno: recibe cuadernos de trabajo de comunicación y matemática de 1er y 2do grado. IE de revitalización: recibe fichas de lengua originaria.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', 'Desde UGEL Puno se consulta qué materiales corresponde a las instituciones educativas de fortalecimiento y revitalización.', ''),
('deib-50', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '50', 'Materiales por lengua: ¿La UGEL 14 (Oyón) con EIB de rehabilitación debe recibir material de quechua central?', 'Materiales por lengua', 'Las instituciones EIB de rehabilitación reciben material según su lengua originaria.', 'Si la UGEL 14 tiene EIB de rehabilitación inicial, primaria y secundaria, ¿deben llegar material que corresponde a quechua central?', 'Todo está en el registro. Todos los materiales llegan de acuerdo al registro de instituciones educativas EIB. A veces llega de un pueblo porque han considerado como segunda lengua otra lengua.', 'IE EIB de rehabilitación en UGEL 14 con quechua central: recibe material en quechua central según el registro nacional.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('deib-51', 'DEIB', 'DEIB', 'Intercultural Bilingüe', '51', 'Error de asignación de material: ¿Hay fichas de la lengua cucamiria que se enviaron a Yurimaguas y son de lengua Shawi?', 'Error de asignación de material', 'Si hay un error en la asignación de material por lengua, se debe corregir con la UGEL.', 'Se indica que hay fichas de la lengua cucamiria que se enviaron a Yurimaguas, pero es de lengua Shawi.', 'Ahí ha habido una confusión seguro. Eso ha sucedido en Yurimaguas porque ahí tienen sus camas. Y también Shawi. Debe haber ahí dialogar directamente con la UGEL. Quizá ha habido una confusión de la llegada. Si la institución educativa Shawi no tendría que llegar cucama y viceversa.', 'IE Shawi en Yurimaguas que recibió fichas de cucamiria: error de asignación. Corregir con la UGEL.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos en lenguas originarias.', '', ''),
('debe-02', 'DEBE', 'DEBE', 'Básica Especial', '02', 'Cobertura de nuevas instituciones: ¿Las instituciones EBE de reciente creación reciben materiales en el 2026?', 'Cobertura de nuevas instituciones', 'Las instituciones de educación básica especial de reciente creación deben ser atendidas por el equipo de educación básica especial.', 'Se consulta si las instituciones educativas EBE de reciente creación para el año 2026 serán asignadas con materiales.', 'Esta es una información que el equipo de educación básica especial tendría que atender. se deriva a la dirección competente para su atención técnica.', 'Una IE EBE creada en 2026 que no recibió material: la consulta debe ser atendida por el equipo de EBE, no por DEI.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('debe-04', 'DEBE', 'DEBE', 'Básica Especial', '04', 'Planificación EBE: ¿Qué indicadores se han encontrado para EBE en el quinquenio de la educación al 2031?', 'Planificación EBE', 'Los indicadores para EBE en el quinquenio de la educación al 2031 deben ser atendidos por el equipo de educación básica especial.', 'Se indica que en el quinquenio de la educación al 2031 no se han encontrado indicadores para los EBE.', 'Esa consulta será atendida por el equipo de educación básica especial. Se toma nota para la coordinación interna.', 'Consulta sobre indicadores EBE al 2031: derivar al equipo de EBE, no es competencia de DEI.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', ''),
('debe-10', 'DEBE', 'DEBE', 'Básica Especial', '10', 'Cantidad por institución: ¿Cuántos libros de Afro Perú 1000 oficios y el pueblo Chavín le corresponden a una unidocente?', 'Cantidad por institución', 'La cantidad de libros de biblioteca depende del número de estudiantes por sección.', 'En una institución educativa unidocente que atiende 3, 4 y 5 años, se consulta cuántos libros de Afro Perú 1000 oficios y el pueblo Chavín le corresponden.', 'Son 4 por institución, pero ahí también va a depender del número de estudiantes que esté en la parte de estadística. Son 4 libros por títulos.', 'Unidocente con 3, 4 y 5 años: recibe 4 ejemplares de cada título (Afro Perú 1000 oficios y Pueblo Chavín) por institución.', 'RM N.° 373-2026-MINEDU — Norma técnica sobre dotación y distribución de materiales educativos para el año lectivo.', '', '')
